-- PT115-S2-Q3. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT115-S2-Q3$batch03$ AND q.stimulus=$batch03$Letter to the editor: Allowing everyone to voice personal views can have the effect of inhibiting some from voicing their concerns. Thus, allowing unrestricted free speech really inhibits free speech.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, does most to justify the apparently contradictory conclusion above?$batch03$ AND q.correct_choice=$batch03$A$batch03$) THEN RAISE EXCEPTION 'Question changed: PT115-S2-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT115-S2-Q3$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S2-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT115-S2-Q3$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Unrestricted free speech lets everyone voice their views.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Unrestricted free speech inhibits free speech?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The first sentence gives the hint: letting everyone speak can stop *some* people from speaking. We need a mechanism. If some views are so forceful or intimidating that other people go quiet, total freedom produces less actual speech from them.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find how unrestricted speech makes some people stop speaking.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT115-S2-Q3$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$People shocked by others' powerful views become afraid to voice their own. Unrestricted speech has silenced them, which is exactly the claim.$batch03$), ($batch03$B$batch03$, $batch03$More views, some offensive. Being offended is not the same as being silenced, so this does not show speech is inhibited.$batch03$), ($batch03$C$batch03$, $batch03$This recommends restricting speech. A recommendation does not explain how unrestricted speech inhibits speech.$batch03$), ($batch03$D$batch03$, $batch03$The salary comparison suggests the claim is absurd. That undermines the conclusion we are supposed to justify.$batch03$), ($batch03$E$batch03$, $batch03$Offended people speak up in reply. That is more speech, not less.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT115-S2-Q3$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
